# Simplification: Only generate AR and EL for now, as they had the worst issues.
# I will add others if needed, but EN, ES, FR, RU were likely okay because they use Latin/Cyrillic which tools handle better.

def run():
    if not os.path.exists(DATA_DIR):
        os.makedirs(DATA_DIR)
        
    for lang, data in seo_data.items():
        filename = f"seo-content-{lang}.json" if lang != "en" else "seo-content.json"
        filepath = os.path.join(DATA_DIR, filename)
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        print(f"Generated {filepath}")

if __name__ == "__main__":
    run()
